local config = {
  ui_story_5062_50620101_1_dialog_content = "How are things along the transportation route? Is the escort team in place?",
  ui_story_5062_50620101_2_dialog_content = "Ma'am, the transportation route is ready to go operational, and the escort team has just set off. ETA is...",
  ui_story_5062_50620101_3_dialog_content = "And local resource extraction?",
  ui_story_5062_50620101_4_dialog_content = "The extraction team has already planned out the extraction route. The first batch of resources will be secured within the day.",
  ui_story_5062_50620101_5_dialog_content = "Grand Marshal, the basic foundations of the outpost have already been laid...",
  ui_story_5062_50620101_6_dialog_content = "However, we're short of hands. For the time being, we will have to assign sentries according to this schedule.",
  ui_story_5062_50620101_7_dialog_content = "And the Eclipsites? Has there been any sight of them?",
  ui_story_5062_50620101_8_dialog_content = "Not as yet. For now, the Twilight perimeter is secure.",
  ui_story_5062_50620101_9_dialog_content = "Understood. Let's go ahead and follow this schedule for now.",
  ui_story_5062_50620101_10_dialog_content = "Grand Marshal, here's a list of requests from our various reconstruction teams.",
  ui_story_5062_50620101_11_dialog_content = "This thing weighs a ton! These willful folks are really happy to order about the new Grand Marshal, aren't they?",
  ui_story_5062_50620101_12_dialog_content = "We're short on personnel as it is... If we don't make a sensible plan, we can hardly push the reconstruction work forward.",
  ui_story_5062_50620101_13_dialog_content = "Commander Wrath?",
  ui_story_5062_50620101_14_dialog_content = "Ah, you made it, PlayerName.",
  ui_story_5062_50620101_15_dialog_content = "Yes, ma'am. PlayerName, reporting for duty.",
  ui_story_5062_50620101_16_dialog_content = "Come on... Technically, Twilight doesn't count as Illumina territory, so you can lose the formalities here.",
  ui_story_5062_50620101_17_dialog_content = "The main reason I called you over here is because I need your help with a few things...",
  ui_story_5062_50620101_18_dialog_content = "As you know, the last battle in Twilight essentially left this town in ruins.",
  ui_story_5062_50620101_19_dialog_content = "The thing is, on paper, part of this place actually is under Illumina's jurisdiction...",
  ui_story_5062_50620101_20_dialog_content = "So the federation decided to have us assist in the reconstruction of Twilight.",
  ui_story_5062_50620101_21_dialog_content = "We're rebuilding Twilight? Awesome!",
  ui_story_5062_50620101_22_dialog_content = "Right, but you see... this kind of organizational work is much harder than commanding troops on the battlefield, at least for me, anyway...",
  ui_story_5062_50620101_23_dialog_content = "After all, this is the kind of thing the Chief of Staff would usually take care of...",
  ui_story_5062_50620101_24_dialog_content = "Grand Marshal Wrath, your performance in commanding and delegating this reconstruction project is central to your assessment.",
  ui_story_5062_50620101_25_dialog_content = "All right. You heard what she said.",
  ui_story_5062_50620101_26_dialog_content = "What assessment?",
  ui_story_5062_50620101_27_dialog_content = "I'll tell you about it later... For now, all I'm gonna say is, I'm glad they still let me seek outside help. That means you, by the way.",
  ui_story_5062_50620101_28_dialog_content = "I know how hard it must be managing things aboard the Colossus with all those people, so I'm guessing you're a natural when it comes to this kind of work.",
  ui_story_5062_50620101_29_dialog_content = "I'll do my best to help out!",
  ui_story_5062_50620101_30_dialog_content = "I was hoping you'd say that.",
  ui_story_5062_50620101_31_dialog_content = "Alright. Then let me brief you on the situations here, PlayerName...",
  ui_story_5062_50620101_32_dialog_content = "Grand Marshal, some locals are gathering outside.",
  ui_story_5062_50620101_33_dialog_content = "Chief of Staff, take care of this for me, will you? I need to speak with PlayerName.",
  ui_story_5062_50620101_34_dialog_content = "Understood.",
  ui_story_5062_50620101_35_dialog_content = "Alright, now let's cut to the chase.",
  ui_story_5062_50620101_36_dialog_content = "The overall planning for the reconstruction work has been completed. That means we're now in the execution phase.",
  ui_story_5062_50620101_37_dialog_content = "Each of Illumina's commanders is responsible for a specific aspect of the reconstruction work.",
  ui_story_5062_50620101_38_dialog_content = "Now, these commanders have proposed a series of requests based on the progress of the reconstruction project, and these requests... well, they're ultimately sent here for us to deal with.",
  ui_story_5062_50620101_39_dialog_content = "As proud members of the Twilight Reconstruction Commission Temporary HQ, this is our oathbound duty.",
  ui_story_5062_50620101_40_dialog_content = "So basically, we have to find competent people to handle all of their requests.",
  ui_story_5062_50620101_41_dialog_content = "I see. Wait, did you say the requests were proposed by the commanders?",
  ui_story_5062_50620101_42_dialog_content = "Yeah. It's nice working alongside familiar people, right?",
  ui_story_5062_50620101_43_dialog_content = "Sure... I mean, no, that's not what I meant...",
  ui_story_5062_50620101_44_dialog_content = "Grand Marshal, are you, the Chief of Staff, and other commanders all here in Twilight?",
  ui_story_5062_50620101_45_dialog_content = "Are you implying that it was too much to involve the commanders and me in the reconstruction of Twilight?",
  ui_story_5062_50620101_46_dialog_content = "Correct.",
  ui_story_5062_50620101_47_dialog_content = "Alas. Nothing gets past you.",
  ui_story_5062_50620101_48_dialog_content = "Didn't you ask why? If I recall correctly, the Eclipsites totally ignored Twilight last time and went straight for Illumina...",
  ui_story_5062_50620101_49_dialog_content = "If everyone's gathered in Twilight...",
  ui_story_5062_50620101_50_dialog_content = "You made a good point, but this is not for me to decide.",
  ui_story_5062_50620101_51_dialog_content = "Those bigshots behind the scenes are dealing with the fallout from the whole Reinhardt mess right now.",
  ui_story_5062_50620101_52_dialog_content = "Before it all blows over, these rebellious little lab rats should stay in a quiet hole. That's it.",
  ui_story_5062_50620101_53_dialog_content = "What?! That's ridiculous.",
  ui_story_5062_50620101_54_dialog_content = "I'm not sure about the details, either. After all, lab rats shouldn't know too much, right?",
  ui_story_5062_50620101_55_dialog_content = "All I know is that, as long as she's there, Illumina's fate doesn't seem all that grim.",
  ui_story_5062_50620101_56_dialog_content = "Grand Marshal Reinhardt?",
  ui_story_5062_50620101_57_dialog_content = "Yes. The way things stand, she's the only one we can count on.",
  ui_story_5062_50620101_58_dialog_content = "And besides whatever line those bigshots are trying to push, I'm equally responsible for not being able to defend this place.",
  ui_story_5062_50620101_59_dialog_content = "Even if it's just for the sake of the townspeople here, I promise I'm gonna accomplish this reconstruction task out of the park!",
  ui_story_5062_50620101_60_dialog_content = "Commander Wrath...",
  ui_story_5062_50620101_61_dialog_content = "Grand Marshal Wrath, I'm back.",
  ui_story_5062_50620101_62_dialog_content = "Ah, perfect timing! We've just finished our little chat too. So, what was that all about just now?",
  ui_story_5062_50620101_63_dialog_content = "Good news. The people of Twilight have volunteered to help us with the reconstruction.",
  ui_story_5062_50620101_64_dialog_content = "Umm. Looks like there are a lot of them. Alright, we need to do what we can to thank them for their enthusiasm.",
  ui_story_5062_50620101_65_dialog_content = "I'll make sure I complete my mission.",
  ui_story_5062_50620101_66_dialog_content = "Then, please follow me. I'll tell you exactly what you need to do.",
  ui_story_5062_50620101_67_dialog_content = "Oh yeah, Officer Vivian. About the assessment you mentioned earlier, was that...",
  ui_story_5062_50620101_68_dialog_content = "Oh, that... What did the Grand Marshal say to you just now?",
  ui_story_5062_50620101_69_dialog_content = "She just shared some of her... speculations regarding the reconstruction task...",
  ui_story_5062_50620101_70_dialog_content = "Well, I can confirm that The Committee did issue an assessment task to the commanders and me.",
  ui_story_5062_50620101_71_dialog_content = "No, it's more like surveillance than an assessment.",
  ui_story_5062_50620101_72_dialog_content = "Interesting...",
  ui_story_5062_50620101_73_dialog_content = "But don't worry, I have nothing but the best of intentions toward Grand Marshal Wrath.",
  ui_story_5062_50620101_74_dialog_content = "I am the Chief of Staff. Making sure the reconstruction work gets completed smoothly is my responsibility.",
  ui_story_5062_50620101_75_dialog_content = "And from what I know, the other commanders simply seem as though they don't want to just follow orders obediently this time.",
  ui_story_5062_50620101_76_dialog_content = "Then what are they doing here?",
  ui_story_5062_50620101_77_dialog_content = "Well, the other commanders have actually already accepted Grand Marshal Wrath, by virtue of her strength.",
  ui_story_5062_50620101_78_dialog_content = "But being a worthy Grand Marshal requires more than battle prowess.",
  ui_story_5062_50620101_79_dialog_content = "So they plan on seizing this chance to put her leadership abilities to the test, on their own terms.",
  ui_story_5062_50620101_80_dialog_content = "Still, I'm not quite sure why I was dragged into this...",
  ui_story_5062_50620101_81_dialog_content = "Should I say some commanders' preferred styles were involved here? Anyway, this is the very kind of thing they would do.",
  ui_story_5062_50620101_82_dialog_content = "The commanders will evaluate each decision the Temporary HQ makes.",
  ui_story_5062_50620101_83_dialog_content = "After this, I will summarize their evaluations into a report and submit it to the Intel Room.",
  ui_story_5062_50620101_84_dialog_content = "Ah, I almost forgot to mention: This matter is to be kept secret from Grand Marshal Wrath for the time being.",
  ui_story_5062_50620101_85_dialog_content = "Understood.",
  ui_story_5062_50620101_86_dialog_content = "And with that, the reconstruction of Twilight officially begins.",
  ui_story_5062_50620101_87_dialog_content = "Could you please assist the Grand Marshal in appointing personnel?",
  ui_story_5062_50620101_88_dialog_content = "On behalf of the Illumina Federation and the citizens of Twilight, I thank you for your support.",
  ui_story_5062_50620102_1_dialog_content = "PlayerName, I'm sorry to bother you, but we'll need your help again with today's reconstruction work.",
  ui_story_5062_50620102_2_dialog_content = "It's no trouble at all! I'm more than okay with it.",
  ui_story_5062_50620102_3_dialog_content = "It feels amazing, watching the town getting rebuilt brick by brick. And I know that any effort I put in here is totally worth it.",
  ui_story_5062_50620102_4_dialog_content = "If you have time, let's head to the Temporary HQ. Grand Marshal Wrath is waiting for you.",
  ui_story_5062_50620102_5_dialog_content = "Grand Marshal Wrath's back? I remember she was summoned back to Illumina a few days ago...",
  ui_story_5062_50620102_6_dialog_content = "If you wish to know more about this matter, you can ask her in person.",
  ui_story_5062_50620102_7_dialog_content = "Hah, PlayerName, here you are.",
  ui_story_5062_50620102_8_dialog_content = "Officer Vivian told me you were looking for me... It looks like a few commanders are here too...",
  ui_story_5062_50620102_9_dialog_content = "Hey! All it took was a few days' hard work and you're already getting stronger.",
  ui_story_5062_50620102_10_dialog_content = "Thanks for the help.",
  ui_story_5062_50620102_11_dialog_content = "Well done.",
  ui_story_5062_50620102_12_dialog_content = "About this assessment... The other commanders have told me about it.",
  ui_story_5062_50620102_13_dialog_content = "Although I never thought I'd see the day you guys would stand with The Committee...",
  ui_story_5062_50620102_14_dialog_content = "Nah, I should've anticipated it. This is your style, commanders.",
  ui_story_5062_50620102_15_dialog_content = "Hahahaha! You're really starting to sound more and more like a Grand Marshal these days.",
  ui_story_5062_50620102_16_dialog_content = "Sorry, but the title of Grand Marshal is no joke. We had no choice but to pull a little trick here.",
  ui_story_5062_50620102_17_dialog_content = "Even so, your performance was exemplary.",
  ui_story_5062_50620102_18_dialog_content = "That's in no small part thanks to PlayerName's help.",
  ui_story_5062_50620102_19_dialog_content = "Indeed, PlayerName's proficiency in dispatch and command operations is outstanding.",
  ui_story_5062_50620102_20_dialog_content = "But knowing people well and making the best use of their abilities is also a quality that a Grand Marshal should possess.",
  ui_story_5062_50620102_21_dialog_content = "Huh? Why are you all staring at me like that? You really want me to share my thoughts too...?",
  ui_story_5062_50620102_22_dialog_content = "Well, to be brief, I have submitted the evaluations written by all commanders present and myself to the senior command of the Illumina Federation.",
  ui_story_5062_50620102_23_dialog_content = "Given her outstanding performance throughout this mission, Grand Marshal Wrath shall be awarded an Illumina Medal of Distinguished Service.",
  ui_story_5062_50620102_24_dialog_content = "In addition, considering the extreme nature of the previous Aid operation, Grand Marshal Wrath's appointment at the time was only temporary.",
  ui_story_5062_50620102_25_dialog_content = "Therefore, a formal inauguration ceremony is likely to be held for Grand Marshal Wrath in the near future.",
  ui_story_5062_50620102_26_dialog_content = "An inauguration ceremony... Hmm, I suppose I should give it some thought.",
  ui_story_5062_50620102_27_dialog_content = "(Give what some thought?)",
  ui_story_5062_50620102_28_dialog_content = "Once the specific arrangements have been finalized, I'll inform everyone of the exact time.",
  ui_story_5062_50620102_29_dialog_content = "See, I told you she could do it.",
  ui_story_5062_50620102_30_dialog_content = "That's not what you were saying at the start.",
  ui_story_5062_50620102_31_dialog_content = "None of that matters anymore—the most important thing now is to restore this war-torn town.",
  ui_story_5062_50620102_32_dialog_content = "Although The Committee has reached a conclusion, our mission to rebuild Twilight isn't over yet.",
  ui_story_5062_50620102_33_dialog_content = "I won't rest until the moment the Temporary HQ is finally packed up.",
  ui_story_5062_50620102_34_dialog_content = "That sounds right.",
  ui_story_5062_50620102_35_dialog_content = "I'll do my best to help everyone too.",
  ui_story_5062_50620102_36_dialog_content = "Hmm. With you here, I'm sure we can rest easy.",
  ui_story_5062_50620102_37_dialog_content = "Of course... Wait a minute—what do you mean you can rest easy with me here?",
  ui_story_5062_50620102_38_dialog_content = "The assessment is over. The commanders will return to Illumina after all follow-up matters are arranged.",
  ui_story_5062_50620102_39_dialog_content = "Our absence will leave a gaping hole in Illumina's defenses. We have to go back.",
  ui_story_5062_50620102_40_dialog_content = "Don't worry. The protocols we've put in place will keep things running.",
  ui_story_5062_50620102_41_dialog_content = "Thanks to the help of the volunteers, even after you all leave, the reconstruction will continue unhindered.",
  ui_story_5062_50620102_42_dialog_content = "PlayerName, all we need to do is carry on as normal.",
  ui_story_5062_50620102_43_dialog_content = "All right, Grand Marshal Wrath, we'll take our leave.",
  ui_story_5062_50620102_44_dialog_content = "Let's go! Keep it up, kid!",
  ui_story_5062_50620102_45_dialog_content = "Farewell.",
  ui_story_5062_50620102_46_dialog_content = "We'll be waiting for you in Illumina.",
  ui_story_5062_50620102_47_dialog_content = "PlayerName, there's something else I'd like to discuss with you.",
  ui_story_5062_50620102_48_dialog_content = "Me?",
  ui_story_5062_50620102_49_dialog_content = "Although the commanders and The Committee gave me positively glowing evaluations...",
  ui_story_5062_50620102_50_dialog_content = "I'm well aware that none of this would have been possible without your help.",
  ui_story_5062_50620102_51_dialog_content = "Sorry for not being able to wangle a medal for you, but here—you can have this.",
  ui_story_5062_50620102_52_dialog_content = "This is...",
  ui_story_5062_50620102_53_dialog_content = "The Illumina Medal of Distinguished Service. Generally, this trinket is only awarded to officers who have made remarkable contributions to Illumina.",
  ui_story_5062_50620102_54_dialog_content = "You mean the one mentioned by Officer Vivian just now? Isn't it awarded to you?",
  ui_story_5062_50620102_55_dialog_content = "Half of this belongs to you... Want me to split it open?",
  ui_story_5062_50620102_56_dialog_content = "Wait! No! You wouldn't seriously do that to something so precious, would you?!",
  ui_story_5062_50620102_57_dialog_content = "Hang on... Why do I get the feeling you're not fooling around?",
  ui_story_5062_50620102_58_dialog_content = "Of course I'm not.",
  ui_story_5062_50620102_59_dialog_content = "Haven't you ever dreamt of receiving a medal like this?",
  ui_story_5062_50620102_60_dialog_content = "Sure, but I want a medal that's all mine—a true recognition for the things I've achieved.",
  ui_story_5062_50620102_61_option_content = "Knowing people well and making the best use of their abilities is worth a medal too!",
  ui_story_5062_50620102_62_dialog_content = "Commander Sharona said just now that knowing people well and making the best use of their abilities is a quality a Grand Marshal should possess.",
  ui_story_5062_50620102_63_dialog_content = "Putting me in a position that gives full play to my talents is also a mark of real skill.",
  ui_story_5062_50620102_64_option_content = "But even so, don't split it in half!",
  ui_story_5062_50620102_65_dialog_content = "This is a medal awarded to officers of Illumina. It wouldn't be right for me to take it.",
  ui_story_5062_50620102_66_dialog_content = "Besides, I just want to help rebuild Twilight. Don't really care about medals.",
  ui_story_5062_50620102_67_dialog_content = "This medal belongs to you. Please keep it properly.",
  ui_story_5062_50620102_68_dialog_content = "Though what you said just now is true, it's only part of the reason this medal is so precious.",
  ui_story_5062_50620102_69_dialog_content = "Even senior officers only get a couple of opportunities to receive this medal in their lifetime.",
  ui_story_5062_50620102_70_dialog_content = "Also... I used to dream about getting one of these.",
  ui_story_5062_50620102_71_dialog_content = "Then why...",
  ui_story_5062_50620102_72_dialog_content = "Why do you think they gave me this medal?",
  ui_story_5062_50620102_73_dialog_content = "For what you've done for Twilight, naturally.",
  ui_story_5062_50620102_74_dialog_content = "Twilight is of no real significance to them, and this reconstruction task was just an excuse to observe me in action.",
  ui_story_5062_50620102_75_dialog_content = "As for this medal... it's nothing but a toy, handed to a lab rat for obeying the rules once again.",
  ui_story_5062_50620102_76_dialog_content = "It burns me up seeing such a great symbol of honor being used to butter someone up like it doesn't mean a thing.",
  ui_story_5062_50620102_77_dialog_content = "Wrath...",
  ui_story_5062_50620102_78_dialog_content = "I won't bite my tongue and be their little lab rat any longer.",
  ui_story_5062_50620102_79_dialog_content = "But whether it's handling this reconstruction project or dealing with those bigshots, I still have a lot to work on.",
  ui_story_5062_50620102_80_dialog_content = "How about you just treat this medal as a thank-you gift from the people of Twilight?",
  ui_story_5062_50620102_81_dialog_content = "Forget about the task. Rebuilding Twilight, in itself, is a feat that'll change the lives of the locals.",
  ui_story_5062_50620102_82_dialog_content = "Even if I almost went into a mad frenzy and destroyed this place?",
  ui_story_5062_50620102_83_dialog_content = "That wasn't your fault.",
  ui_story_5062_50620102_84_dialog_content = "I know... Just kidding.",
  ui_story_5062_50620102_85_dialog_content = "All right, I'll keep it as a memento. But next time, I'm gonna get a medal for my exploits on the battlefield and accept it with integrity.",
  ui_story_5062_50620102_86_dialog_content = "Before that, we need to take care of the task at hand.",
  ui_story_5062_50620102_87_dialog_content = "You're right. I'm ready to start today's work.",
  ui_story_5062_50620102_88_dialog_content = "Come on, PlayerName. Let's go out for a little walk before work.",
  ui_story_5062_50620102_89_dialog_content = "Walk with me, Caelestite. Let's take a look at the Twilight we helped rebuild.",
  ui_story_5062_50620103_1_dialog_content = "This is Wrath here. Please reply if you can hear me.",
  ui_story_5062_50620103_2_dialog_content = "Roger. This is Gram.",
  ui_story_5062_50620103_3_dialog_content = "Report your current situation.",
  ui_story_5062_50620103_4_dialog_content = "At the mission area perimeter, preparing to enter.",
  ui_story_5062_50620103_5_dialog_content = "Comms are clear, and supplies are sufficient. So far, so good... except...",
  ui_story_5062_50620103_6_dialog_content = "Except what?",
  ui_story_5062_50620103_7_dialog_content = "Except Benny and Revy have been constantly clambering over each other for a chance to fight some Eclipsites.",
  ui_story_5062_50620103_8_dialog_content = "They're excellent fighters when it comes to their individual talents and the ideal choice for a small-scale exploration mission like this.",
  ui_story_5062_50620103_9_dialog_content = "But our intelligence officer claims they are so noisy that she can't even sleep soundly at night!",
  ui_story_5062_50620103_10_dialog_content = "Hmm... When it comes to handling intel, no one even comes close to her.",
  ui_story_5062_50620103_11_dialog_content = "Oh yeah, and there seems to be something strange floating around Chandra.",
  ui_story_5062_50620103_12_dialog_content = "The environment of this operation is special. Therefore, psychological counseling is essential for combat personnel.",
  ui_story_5062_50620103_13_dialog_content = "As for any other issues, they can be ignored for now.",
  ui_story_5062_50620103_14_dialog_content = "Roger. Then all the things are good.",
  ui_story_5062_50620103_15_dialog_content = "OK. Now let me brief you one your mission one more time.",
  ui_story_5062_50620103_16_dialog_content = "This time, you'll be starting from Twilight, proceeding to explore the borders of the eternal night.",
  ui_story_5062_50620103_17_dialog_content = "We must monitor Eclipsite activity as closely as we can to prevent another surprise attack.",
  ui_story_5062_50620103_18_dialog_content = "Understood.",
  ui_story_5062_50620103_19_dialog_content = "I'll sync the coordinates of this plan's exploration locations with you later.",
  ui_story_5062_50620103_20_dialog_content = "As for any unplanned occurrences, you'll have to draw on your experience and adapt to the situation accordingly.",
  ui_story_5062_50620103_21_dialog_content = "Thinking on your feet—my favorite kind.",
  ui_story_5062_50620103_22_dialog_content = "Don't forget, this is an exploration mission. Just do your recon job.",
  ui_story_5062_50620103_23_dialog_content = "So, if we run into the enemy, we should save the heroics for another day and retreat immediately, yes?",
  ui_story_5062_50620103_24_dialog_content = "Yes. I'm confident that you'll be able to handle any situation that comes your way.",
  ui_story_5062_50620103_25_dialog_content = "What?! Retreat?! Why don't we just blow 'em all to smithereens! Kaboom!",
  ui_story_5062_50620103_26_dialog_content = "Enough... Still remember the mission objective? We're not supposed to—",
  ui_story_5062_50620103_27_dialog_content = "How about a little wager? Let's see who can take down more Eclipsites! What d'you say?!",
  ui_story_5062_50620103_28_dialog_content = "Hey! Don't just swing your weapons around like that!",
  ui_story_5062_50620103_29_dialog_content = "You're on! Curo, count for me, will ya?",
  ui_story_5062_50620103_30_dialog_content = "Sorry, Captain, I'll keep a hold on both of them...",
  ui_story_5062_50620103_31_dialog_content = "Allow me to assist!",
  ui_story_5062_50620103_32_dialog_content = "Benny, leave that bag alone! Those are our rations!",
  ui_story_5062_50620103_33_dialog_content = "Hmm? Did I hear someone say \"rations,\" meow?",
  ui_story_5062_50620103_34_dialog_content = "Dried fish! Dried fish!",
  ui_story_5062_50620103_35_dialog_content = "No dried fish here! Combat rations need to be high in calories. Everything you see here was prepared by yours truly.",
  ui_story_5062_50620103_36_dialog_content = "This smell... This smell! Meow... Could it be...?",
  ui_story_5062_50620103_37_dialog_content = "It seems to be some kind of cheese product.",
  ui_story_5062_50620103_38_dialog_content = "Cheese! Aww, why does it have to be cheese?! Meow!",
  ui_story_5062_50620103_39_dialog_content = "Philyshy, please don't waste our supplies!",
  ui_story_5062_50620103_40_dialog_content = "This is one lively team! It reminds me of those days with the Stone Force.",
  ui_story_5062_50620103_41_dialog_content = "Back then, I was just like they are now... Hmm, what's the word... that's it—wild!",
  ui_story_5062_50620103_42_dialog_content = "Maintain regular contact on the hour and report on arrival at the target point or if any other situations come up.",
  ui_story_5062_50620103_43_dialog_content = "Alright, we already went through all this well enough before the mission.",
  ui_story_5062_50620103_44_dialog_content = "We know next to nothing about what might be waiting for us beyond the line of defense. Stay vigilant.",
  ui_story_5062_50620103_45_dialog_content = "Understood. I just wish we could get this over with instead of having you ramble on and on...",
  ui_story_5062_50620103_46_dialog_content = "I'll do my best to kick these old habits of mine... I won't let what happened back then happen again.",
  ui_story_5062_50620103_47_dialog_content = "Sorry to put you on this mission. It's kinda improvising.",
  ui_story_5062_50620103_48_dialog_content = "Few people are competent enough to be dispatched to the border. I just didn't have much of a choice.",
  ui_story_5062_50620103_49_dialog_content = "That's alright. I'm a soldier. The battlefield is my home.",
  ui_story_5062_50620103_50_dialog_content = "And so much for chit-chat. Judging from the diminishing light in the environment, I'd say we've entered the mission area.",
  ui_story_5062_50620103_51_dialog_content = "Keep a close eye out for movement in your surroundings. I'll sync the coordinates of the first target point with you.",
  ui_story_5062_50620103_52_dialog_content = "Understood.",
  ui_story_5062_50620103_53_dialog_content = "Miss Intelligence Officer, confirm your intelligence on the target point, please.",
  ui_story_5062_50620103_54_dialog_content = "How come we still have to work when we don't even have dried fish, meow...?",
  ui_story_5062_50620103_55_dialog_content = "Got visual on the target location. Ready to begin the exploration mission.",
  ui_story_5062_50620103_56_dialog_content = "We're here? Let me take the lead then!",
  ui_story_5062_50620103_57_dialog_content = "What?! If anyone's gonna be captain, it's gonna be me! How about we fight for it?",
  ui_story_5062_50620103_58_dialog_content = "Obviously, Mr. Gram is the captain... Curo, can't you stop them?",
  ui_story_5062_50620103_59_dialog_content = "I've got nothing to do with those idiots...",
  ui_story_5062_50620103_60_dialog_content = "Gram, there's just one more thing.",
  ui_story_5062_50620103_61_dialog_content = "Go ahead, Grand Marshal.",
  ui_story_5062_50620103_62_dialog_content = "... Being captain of this squad isn't an easy job. Thank you."
}
return config
